import React, { useEffect, useState } from 'react';

function App() {
  const [defender, setDefender] = useState('A Measly Worm');
  const [winner, setWinner] = useState('A Measly Worm');
  const [numberOfTimes, setNumberOfTimes] = useState(0);
  const [victoryReason, setVictoryReason] = useState('It is a measly worm');
  const [emoji, setEmoji] = useState('🐛');

  const fetchAttacker = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/data');
      const data = await response.json();
      setDefender(data.defender);
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  // useEffect(() => {
  //   fetchAttacker();
  // }, []);

  const [input, setInput] = useState('');

  const handleSend = async () => {
    try {
      await fetch('http://localhost:3000/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input }),
      });
      setInput('');
    } catch (err) {
      console.error('Error sending message:', err);
    }
    fetchAttacker();
  };

  return (
    <div>
      <h1>{defender}</h1>
      <input
        type="text"
        value={input}
        onChange={e => setInput(e.target.value)}
        placeholder="Type your message"
      />
      <button onClick={handleSend}>Send</button>
    </div>
  );
}

export default App;
